export function normalize(draws) {
  if (!Array.isArray(draws)) throw new Error('Unexpected lottery response');
  const seen = new Set();
  return draws.map(d => ({id:Number(d.drawNumber), numbers:d.winningNumbers, bonus:d.bonus})).filter(d => {
    if (!Number.isInteger(d.id) || seen.has(d.id)) return false;
    if (!Array.isArray(d.numbers) || d.numbers.length !== 20 || new Set(d.numbers).size !== 20 || d.numbers.some(n => !Number.isInteger(n) || n < 1 || n > 80)) throw new Error('Invalid draw data');
    seen.add(d.id); return true;
  }).sort((a,b)=>a.id-b.id);
}
export default {async fetch(request) {
  const url = new URL(request.url);
  if (url.pathname === '/api/results') {
    const date = url.searchParams.get('date');
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date || '') || (!Number.isFinite(Date.parse(date+'T12:00:00Z')) || new Date(date+'T12:00:00Z').toISOString().slice(0,10)!==date)) return Response.json({error:'Choose a valid date.'},{status:400});
    try {
      // Same-origin server proxy avoids depending on the Lottery's browser CORS policy.
      const upstream = await fetch('https://www.masslottery.com/rest/keno/getDrawsByDateRange?startDate='+date+'&endDate='+date,{headers:{Accept:'application/json'},signal:AbortSignal.timeout(15000)});
      if (!upstream.ok) throw new Error('Lottery service unavailable');
      const data = await upstream.json();
      return Response.json({date,draws:normalize(data.draws),updatedAt:new Date().toISOString()},{headers:{'Cache-Control':'public, max-age=30'}});
    } catch { return Response.json({error:'The Mass Lottery feed is temporarily unavailable. Please try again.'},{status:502}); }
  }
  if(url.pathname==='/venmo-qr.jpg') return new Response(Uint8Array.from(atob(venmoQr), c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/jpeg','Cache-Control':'public, max-age=86400'}});
  if(url.pathname==='/brand-art.jpg') return new Response(Uint8Array.from(atob(brandArt), c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/jpeg','Cache-Control':'public, max-age=86400'}});
  if(url.pathname!=='/') return new Response('Not found',{status:404});
  return new Response(html,{headers:{'Content-Type':'text/html; charset=utf-8'}});
}};
